window.AUTH=window.AUTH||{};window.AUTH["22-888"]={"d":"22-888","id":"2023/22-888","n":"Rudisill v. McDonough","briefs":[{"k":"petitioner","label":"Brief of petitioner James R. Rudisill","date":"2023-08-10","url":"https://www.supremecourt.gov/DocketPDF/22/22-888/275044/20230810125518713_Rudisill%20v.%20McDonough%20-%20Brief%20For%20Petitioner.pdf","side":"pet","n":60},{"k":"respondent","label":"Brief of respondent Denis McDonough, Secretary of Veterans Affairs","date":"2023-09-11","url":"https://www.supremecourt.gov/DocketPDF/22/22-888/279347/20230911181052651_22-888bsUnitedStates.pdf","side":"res","n":69},{"k":"reply","label":"Reply of petitioner James R. Rudisill","date":"2023-10-11","url":"https://www.supremecourt.gov/DocketPDF/22/22-888/284679/20231011124351848_22-888_Reply%20brief.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r16_2dp3.pdf","tr":true,"items":[{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"by":{"0":"44"}},{"t":"case","label":"Boone v. Lightner","cite":"319 U.S. 561","y":1943,"id":"scdb/1942-138","sc":1,"by":{"0":"37, 58, 59"},"q":[{"src":"brief","b":0,"text":"liberally construed to protect those who have been obliged to drop their own affairs and take up the burdens of the nation,","cite":"319 U.S. 561, 575"},{"src":"brief","b":0,"text":"be liberally construed to protect those who have been obliged to drop their own affairs and take up the burdens of the nation.","cite":"319 U.S. at 575"}]},{"t":"case","label":"BP Am. Prod. Co. v. Burton","cite":"549 U.S. 84","y":2006,"id":"2006/05-669","sc":1,"by":{"0":"37"}},{"t":"case","label":"Brown v. Bd. of Educ.","cite":"347 U.S. 483","y":1954,"id":"1940-1955/347us483","sc":1,"by":{"0":"8"}},{"t":"case","label":"Carr v. Wilkie","cite":"961 F.3d 1168","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/961/1168/","by":{"0":"12"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"by":{"0":"37, 54","2":"6"},"q":[{"src":"brief","b":0,"text":"an absurd and unjust result which Congress could not have intended.","cite":"524 U.S. 417, 429"}]},{"t":"case","label":"Fishgold v. Sullivan Drydock & Repair Corp.","cite":"328 U.S. 275","y":1946,"id":"scdb/1945-102","sc":1,"by":{"0":"58"},"q":[{"src":"brief","b":0,"text":"as parts of an organic whole and give each as liberal a construction for the benefit of the veteran as harmonious interplay of the separate provisions permits.","cite":"328 U.S. 275, 285"}]},{"t":"case","label":"Fla. Dep’t of Rev. v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"by":{"0":"37, 48"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"59","1":"31","2":"25, 26"},"q":[{"src":"brief","b":2,"text":"faithfully applies Congress’s longstanding solicitude for veterans, recognizing that Congress has already placed its own ‘thumb on the scale in the veteran’s favor in the course of . . . judicial review of VA decisions.’","cite":"562 U.S. at 440"}]},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"provisions for benefits to members of the Armed Services are to be construed in the beneficiaries’ favor,","cite":"502 U.S. 215, 220 n.9"}]},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting Grp., Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"by":{"0":"52"}},{"t":"case","label":"Opati v. Republic of Sudan","cite":"140 S. Ct. 1601","y":2020,"id":"2019/17-1268","sc":1,"by":{"0":"44"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"by":{"0":"37"}},{"t":"case","label":"Rowland v. Cal. Men’s Colony","cite":"506 U.S. 194","y":1993,"id":"1992/91-1188","sc":1,"by":{"0":"37, 48, 53"},"q":[{"src":"brief","b":0,"text":"the texts of other related congressional Acts,","cite":"506 U.S. 194, 199"}]},{"t":"case","label":"Rudisill v. Chesapeake & Ohio Ry. Co.","cite":"167 F.2d 175","y":1948,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/167/175/","by":{"0":"59"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"0":"50"}},{"t":"usc","label":"10 U.S.C. § 1143","url":"https://www.law.cornell.edu/uscode/text/10/1143","by":{"0":"7"}},{"t":"usc","label":"10 U.S.C. § 2141","url":"https://www.law.cornell.edu/uscode/text/10/2141","by":{"0":"7"}},{"t":"usc","label":"10 U.S.C. § 16131","url":"https://www.law.cornell.edu/uscode/text/10/16131","by":{"0":"7, 11"}},{"t":"usc","label":"10 U.S.C. § 16163","url":"https://www.law.cornell.edu/uscode/text/10/16163","by":{"0":"14"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"5"}},{"t":"usc","label":"38 U.S.C. § 3001","url":"https://www.law.cornell.edu/uscode/text/38/3001","by":{"0":"13","1":"2"}},{"t":"usc","label":"38 U.S.C. § 3011","url":"https://www.law.cornell.edu/uscode/text/38/3011","subs":["(a)","(a)(1)(A)","(a)(1)(A)(i)","(b)"],"stext":{"head":"§3011. Basic educational assistance entitlement for service on active duty","paras":[[0,"(a) Except as provided in subsection (c) of this section, each individual—"],[1,"(1) who—"],[2,"(A) during the period beginning July 1, 1985, and ending September 30, 2030, first becomes a member of the Armed Forces or first enters on active duty as a member of the Armed Forces and—"],[3,"(i) who (I) in the case of an individual whose obligated period of active duty is three years or more, serves at least three years of continuous active duty in the Armed Forces, or (II) in the case of an individual whose obligated period of active duty is less than three years, serves at least two years of continuous active duty in the Armed Forces; or"],[3,"(ii) who serves in the Armed Forces and is discharged or released from active duty (I) for a service-connected disability, by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10), for a medical condition which preexisted such service on active duty and which the Secretary determines is not service connected, for hardship, or for a physical or mental condition that was not characterized as a disability and did not result from the individual's own willful misconduct but did interfere with the individual's performance of duty, as determined by the Secretary of each military department in accordance with regulations prescribed by the Secretary of Defense or by the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy; (II) for the convenience of the Government, if, in the case of an individual with an obligated period of service of two years, the individual completes not less than 20 months of continuous active duty under that period of obligated service, or, in the case of an individual with an obligated period of service of at least three years, the individual completes not less than 30 months of continuous active duty under that period of obligated service; or (III) involuntarily for the convenience of the Government as a result of a reduction in force, as determined by the Secretary of the military department concerned in accordance with regulations prescribed by the Secretary of Defense or by the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy;"],[2,"(B) as of December 31, 1989, is eligible for educational assistance benefits under chapter 34 of this title and was on active duty at any time during the period beginning on October 19, 1984, and ending on July 1, 1985, continued on active duty without a break in service and—"],[3,"(i) after June 30, 1985, serves at least three years of continuous active duty in the Armed Forces; or"],[3,"(ii) after June 30, 1985, is discharged or released from active duty (I) for a service-connected disability, by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10), for a medical condition which preexisted such service on active duty and which the Secretary determines is not service connected, for hardship, or for a physical or mental condition that was not characterized as a disability, as described in subparagraph (A)(ii)(I) of this paragraph; (II) for the convenience of the Government, if the individual completed not less than 30 months of continuous active duty after that date; or (III) involuntarily for the convenience of the Government as a result of a reduction in force, as determined by the Secretary of the military department concerned in accordance with regulations prescribed by the Secretary of Defense or by the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy; or"],[2,"(C) as of December 31, 1989, was eligible for educational assistance benefits under chapter 34 of this title and—"],[3,"(i) was not on active duty on October 19, 1984;"],[3,"(ii) reenlists or reenters on a period of active duty after October 19, 1984; and"],[3,"(iii) on or after July 1, 1985, either—"],[4,"(I) serves at least three years of continuous active duty in the Armed Forces; or"],[4,"(II) is discharged or released from active duty (aa) for a service-connected disability, by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10), for a medical condition which preexisted such service on active duty and which the Secretary determines is not service connected, for hardship, or for a physical or mental condition that was not characterized as a disability, as described in subparagraph (A)(ii)(I) of this paragraph, (bb) for the convenience of the Government, if the individual completed not less than 30 months of continuous active duty after that date, or (cc) involuntarily for the convenience of the Government as a result of a reduction in force, as determined by the Secretary of the military department concerned in accordance with regulations prescribed by the Secretary of Defense or by the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy;"],[1,"(2) who completes the requirements of a secondary school diploma (or equivalency certificate), or successfully completes (or otherwise receives academic credit for) the equivalent of 12 semester hours in a program of education leading to a standard college degree, before applying for benefits under this section; and"],[1,"(3) who, after completion of the service described in clause (1) of this subsection—"],[2,"(A) continues on active duty;"],[2,"(B) is discharged from active duty with an honorable discharge;"],[2,"(C) is released after service on active duty characterized by the Secretary concerned as honorable service and is placed on the retired list, is transferred to the Fleet Reserve or Fleet Marine Corps Reserve, or is placed on the temporary disability retired list; or"],[2,"(D) is released from active duty for further service in a reserve component of the Armed Forces or for further service in the Space Force in a space force active status not on sustained duty under section 20105 of title 10 after service on active duty characterized by the Secretary concerned as honorable service;"],[0,"is entitled to basic educational assistance under this chapter."],[0,"(b)(1) Except as provided in paragraph (2), the basic pay of any individual described in subsection (a)(1)(A) of this section who does not make an election under subsection (c)(1) of this section shall be reduced by $100 for each of the first 12 months that begin after the date that is 270 days after the date on which the individual initially enters initial training."],[0,"(2) In the case of an individual covered by paragraph (1) who is a member of the Selected Reserve, the Secretary of Defense shall collect from the individual an amount equal to $1,200 not later than one year after completion by the individual of the two years of service on active duty providing the basis for such entitlement. The Secretary of Defense may collect such amount through reductions in basic pay in accordance with paragraph (1) or through such other method as the Secretary of Defense considers appropriate."],[0,"(3) Any amount by which the basic pay of an individual is reduced under this subsection shall revert to the Treasury and shall not, for purposes of any Federal law, be considered to have been received by or to be within the control of such individual."],[0,"(c)(1) An individual described in subsection (a)(1)(A) of this section may make an election not to receive educational assistance under this chapter. Any such election shall be made during the 90-day period beginning on the day that is 180 days after the date on which the individual initially enters initial training. Any individual who makes such an election is not entitled to educational assistance under this chapter."],[0,"(2) An individual who after December 31, 1976, receives a commission as an officer in the Armed Forces upon graduation from the United States Military Academy, the United States Naval Academy, the United States Air Force Academy, or the Coast Guard Academy is not eligible for educational assistance under this section."],[0,"(3) An individual who after December 31, 1976, receives a commission as an officer in the Armed Forces upon completion of a program of educational assistance under section 2107 of title 10 is not eligible for educational assistance under this section if the individual enters on active duty—"],[1,"(A) before October 1, 1996; or"],[1,"(B) after September 30, 1996, and while participating in such program received more than $3,400 for each year of such participation."],[0,"(d)(1) For purposes of this chapter, any period of service described in paragraphs (2) and (3) of this subsection shall not be considered a part of an obligated period of active duty on which an individual's entitlement to assistance under this section is based."],[0,"(2) The period of service referred to in paragraph (1) is any period terminated because of a defective enlistment and induction based on—"],[1,"(A) the individual's being a minor for purposes of service in the Armed Forces;"],[1,"(B) an erroneous enlistment or induction; or"],[1,"(C) a defective enlistment agreement."],[0,"(3) The period of service referred to in paragraph (1) is also any period of service on active duty which an individual in the Selected Reserve was ordered to perform under section 12301, 12302, 12304, 12306, or 12307 of title 10 for a period of less than 2 years."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3011?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 13, 14, 17, 18, 25, 38, 39, 41, 56","1":"2, 3, 2, 19, 3","2":"3"},"q":[{"src":"brief","b":0,"text":"the period beginning July 1, 1985, and ending September 30, 2030,","cite":"38 U.S.C. § 3011(a)"}]},{"t":"usc","label":"38 U.S.C. § 3013","url":"https://www.law.cornell.edu/uscode/text/38/3013","subs":["(a)(1)"],"by":{"0":"11, 13, 17, 49","1":"2, 28","2":"4"}},{"t":"usc","label":"38 U.S.C. § 3014","url":"https://www.law.cornell.edu/uscode/text/38/3014","subs":["(a)"],"by":{"0":"13, 49","1":"3"}},{"t":"usc","label":"38 U.S.C. § 3015","url":"https://www.law.cornell.edu/uscode/text/38/3015","by":{"0":"23","1":"3"}},{"t":"usc","label":"38 U.S.C. § 3018A","url":"https://www.law.cornell.edu/uscode/text/38/3018A","by":{"0":"18"}},{"t":"usc","label":"38 U.S.C. § 3018B","url":"https://www.law.cornell.edu/uscode/text/38/3018B","by":{"0":"18"}},{"t":"usc","label":"38 U.S.C. § 3033","url":"https://www.law.cornell.edu/uscode/text/38/3033","by":{"0":"11","2":"14"},"q":[{"src":"brief","b":2,"text":"may not receive assistance under two or more of such programs concurrently but shall elect . . . under which program to receive educational assistance.","cite":"38 U.S.C. § 3033(a)(1)"}]},{"t":"usc","label":"38 U.S.C. § 3201","url":"https://www.law.cornell.edu/uscode/text/38/3201","by":{"0":"7"}},{"t":"usc","label":"38 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/38/3231","by":{"0":"11, 12, 13"}},{"t":"usc","label":"38 U.S.C. § 3301","url":"https://www.law.cornell.edu/uscode/text/38/3301","stext":{"head":"§3301. Definitions","paras":[[0,"In this chapter:"],[1,"(1) The term \"active duty\" has the meanings as follows (subject to the limitations specified in sections 3002(6) and 3311(b)):"],[2,"(A) In the case of members of the regular components of the Armed Forces, the meaning given such term in section 101(21)(A)."],[2,"(B) In the case of members of the reserve components of the Armed Forces, service on active duty under a call or order to active duty under section 688, 12301(a), 12301(d), 12301(g), 12301(h), 12302, 12304, 12304a, or 12304b of title 10 or section 712 1 of title 14."],[2,"(C) In the case of a member of the Army National Guard of the United States or Air National Guard of the United States, in addition to service described in subparagraph (B), full-time service—"],[3,"(i) in the National Guard of a State for the purpose of organizing, administering, recruiting, instructing, or training the National Guard; or"],[3,"(ii) in the National Guard under section 502(f) of title 32 when authorized by the President or the Secretary of Defense for the purpose of responding to a national emergency declared by the President and supported by Federal funds."],[1,"(2) The term \"emergency situation\" has the meaning given such term in section 3601 of this title."],[1,"(3) The term \"entry level and skill training\" means the following:"],[2,"(A) In the case of members of the Army, Basic Combat Training and Advanced Individual Training or One Station Unit Training."],[2,"(B) In the case of members of the Navy, Recruit Training (or Boot Camp) and Skill Training (or so-called \"A\" School)."],[2,"(C) In the case of members of the Air Force or the Space Force, Basic Military Training and Technical Training."],[2,"(D) In the case of members of the Marine Corps, Recruit Training and Marine Corps Training (or School of Infantry Training)."],[2,"(E) In the case of members of the Coast Guard, Basic Training and Skill Training (or so-called \"A\" School)."],[1,"(4) The term \"program of education\" has the meaning given such term in section 3002, except to the extent otherwise provided in section 3313."],[1,"(5) The term \"Secretary of Defense\" means the Secretary of Defense, except that the term means the Secretary of Homeland Security with respect to the Coast Guard when it is not operating as a service in the Navy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3301?type=usc&year=mostrecent&link-type=html"},"by":{"0":"6, 14, 15, 17, 48","1":"2","2":"2, 13, 22"},"q":[{"src":"brief","b":0,"text":"provide veterans who serve on active duty in the Armed Forces after September 11, 2001, with enhanced educational assistance benefits that are worthy of such service.","cite":"38 U.S.C. § 3301"}]},{"t":"usc","label":"38 U.S.C. § 3311","url":"https://www.law.cornell.edu/uscode/text/38/3311","subs":["(b)","(b)(1)(A)"],"stext":{"head":"§3311. Educational assistance for service in the Armed Forces commencing on or after September 11, 2001: entitlement","paras":[[0,"(a) Entitlement.—Subject to subsections (d) and (e), each individual described in subsection (b) is entitled to educational assistance under this chapter."],[0,"(b) Covered Individuals.—An individual described in this subsection is any individual as follows:"],[1,"(1) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 36 months on active duty in the Armed Forces (including service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty; or"],[3,"(ii) is discharged or released from active duty as described in subsection (c)."],[1,"(2) An individual—"],[2,"(A) who—"],[3,"(i) commencing on or after September 11, 2001, serves at least 30 continuous days on active duty in the Armed Forces; and"],[3,"(ii) after completion of service described in clause (i), is discharged or released from active duty in the Armed Forces for a service-connected disability or by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10); or"],[2,"(B) who—"],[3,"(i) commencing on or after September 11, 2001, completes at least 30 continuous days of service described in subsection (d)(1) or (2); and"],[3,"(ii) after completion of service described in clause (i), is discharged or released by reason of a sole survivorship discharge (as that term is defined in section 1174(i) of title 10)."],[1,"(3) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 30 months, but less than 36 months, on active duty in the Armed Forces (including service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 36 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 36 months, is discharged or released from active duty as described in subsection (c)."],[1,"(4) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 24 months, but less than 30 months, on active duty in the Armed Forces (including service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 30 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 30 months, is discharged or released from active duty as described in subsection (c)."],[1,"(5) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 18 months, but less than 24 months, on active duty in the Armed Forces (excluding service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 24 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 24 months, is discharged or released from active duty as described in subsection (c)."],[1,"(6) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 6 months, but less than 18 months, on active duty in the Armed Forces (excluding service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 18 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 18 months, is discharged or released from active duty as described in subsection (c)."],[1,"(7) An individual who—"],[2,"(A) commencing on or after September 11, 2001, serves an aggregate of at least 90 days, but less than 6 months, on active duty in the Armed Forces (excluding service on active duty in entry level and skill training); and"],[2,"(B) after completion of service described in subparagraph (A)—"],[3,"(i) continues on active duty for an aggregate of less than 6 months; or"],[3,"(ii) before completion of service on active duty of an aggregate of 6 months, is discharged or released from active duty as described in subsection (c)."],[1,"(8) An individual who is the child or spouse of a person who, on or after September 11, 2001, dies in line of duty while serving on active duty as a member of the Armed Forces."],[1,"(9) An individual who is the child or spouse of a person who, on or after September 11, 2001, dies in line of duty while serving on duty other than active duty as a member of the Armed Forces."],[1,"(10) An individual who is the child or spouse of a member of the Selected Reserve who dies on or after September 11, 2001, while a member of the Selected Reserve from a service-connected disability."],[1,"(11) An individual who is awarded the Purple Heart for service in the Armed Forces occurring on or after September 11, 2001, and continues to serve on active duty in the Armed Forces or is discharged or released from active duty as described in subsection (c)."],[0,"(c) Covered Discharges and Releases.—A discharge or release from active duty of an individual described in this subsection is a discharge or release as follows:"],[1,"(1) A discharge from active duty in the Armed Forces with an honorable discharge."],[1,"(2) A release after service on active duty in the Armed Forces characterized by the Secretary concerned as honorable service and placement on the retired list, transfer to the Fleet Reserve or Fleet Marine Corps Reserve, or placement on the temporary disability retired list."],[1,"(3) A release from active duty in the Armed Forces for further service in a reserve component of the Armed Forces, or for further service in the Space Force in a space force active status not on sustained duty under section 20105 of title 10, after service on active duty characterized by the Secretary concerned as honorable service."],[1,"(4) A discharge or release from active duty in the Armed Forces after service on active duty in the Armed Forces characterized by the Secretary concerned as honorable service for—"],[2,"(A) a medical condition which preexisted the service of the individual as described in the applicable paragraph of subsection (b) and which the Secretary determines is not service-connected;"],[2,"(B) hardship; or"],[2,"(C) a physical or mental condition that was not characterized as a disability and did not result from the individual's own willful misconduct but did interfere with the individual's performance of duty, as determined by the Secretary concerned in accordance with regulations prescribed by the Secretary of Defense."],[0,"(d) Prohibition on Treatment of Certain Service as Period of Active Duty.—Except as provided in subsection (b)(2)(B), the following periods of service shall not be considered a part of the period of active duty on which an individual's entitlement to educational assistance under this chapter is based:"],[1,"(1) A period of service on active duty of an officer pursuant to an agreement under section 2107(b) of title 10."],[1,"(2) A period of service on active duty of an officer pursuant to an agreement under section 7448, 8459, or 9448 of title 10 or section 182 1 of title 14."],[1,"(3) A period of service that is terminated because of a defective enlistment and induction based on—"],[2,"(A) the individual's being a minor for purposes of service in the Armed Forces;"],[2,"(B) an erroneous enlistment or induction; or"],[2,"(C) a defective enlistment agreement."],[0,"(e) Treatment of Individuals Entitled Under Multiple Provisions.—In the event an individual entitled to educational assistance under this chapter is entitled by reason of both paragraphs (4) and (5) of subsection (b), the individual shall be treated as being entitled to educational assistance under this chapter by reason of paragraph (5) of subsection (b)."],[0,"(f) Marine Gunnery Sergeant John David Fry Scholarship.—"],[1,"(1) In general.—Educational assistance payable by reason of paragraphs (8), (9), and (10) of subsection (b) shall be known as the \"Marine Gunnery Sergeant John David Fry scholarship\"."],[1,"(2) Election on receipt of certain benefits.—Except as provided in paragraph (3), a surviving spouse entitled to assistance under subsection (a) pursuant to paragraphs (8), (9), and (10) of subsection (b) who is also entitled to educational assistance under chapter 35 of this title may not receive assistance under both this section and such chapter, but shall make an irrevocable election (in such form and manner as the Secretary may prescribe) under which section or chapter to receive educational assistance."],[1,"(3) Exception for certain elections.—"],[2,"(A) In general.—An election made under paragraph (2) by a spouse described in subparagraph (B) may not be treated as irrevocable if such election occurred before the date of the enactment of this paragraph."],[2,"(B) Eligible surviving spouse.—A spouse described in this subparagraph is an individual—"],[3,"(i) who is entitled to assistance under subsection (a) pursuant to paragraphs (8), (9), and (10) of subsection (b); and"],[3,"(ii) who was the spouse of a member of the Armed Forces who died during the period beginning on September 11, 2001, and ending on December 31, 2005."],[1,"(4) Definition of child.—For purposes of paragraphs (8), (9), and (10) of subsection (b), the term \"child\" includes a married individual or an individual who is above the age of twenty-three years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3311?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 16, 17, 39, 41, 47, 49","1":"2, 3, 19","2":"1, 4"},"q":[{"src":"brief","b":0,"text":"on or after September 11, 2001.","cite":"38 U.S.C. § 3311(a)"},{"src":"argument","who":"Mr. Tseytlin","text":"Chief Justice, and may it please the Court: In Section 3311 of the Post-9/11 GI Bill, Congress awarded veterans who served after the September 11th attacks with an entitlement to wartime benefits befitting their wartime service."}]},{"t":"usc","label":"38 U.S.C. § 3312","url":"https://www.law.cornell.edu/uscode/text/38/3312","subs":["(a)"],"by":{"0":"11, 17","1":"2, 28","2":"4"}},{"t":"usc","label":"38 U.S.C. § 3313","url":"https://www.law.cornell.edu/uscode/text/38/3313","subs":["(a)"],"by":{"0":"15, 16, 49","1":"3, 3"}},{"t":"usc","label":"38 U.S.C. § 3315","url":"https://www.law.cornell.edu/uscode/text/38/3315","by":{"0":"15, 49"}},{"t":"usc","label":"38 U.S.C. § 3316","url":"https://www.law.cornell.edu/uscode/text/38/3316","by":{"0":"15, 49, 58"}},{"t":"usc","label":"38 U.S.C. § 3317","url":"https://www.law.cornell.edu/uscode/text/38/3317","by":{"0":"15, 49"}},{"t":"usc","label":"38 U.S.C. § 3318","url":"https://www.law.cornell.edu/uscode/text/38/3318","by":{"0":"15, 49"}},{"t":"usc","label":"38 U.S.C. § 3319","url":"https://www.law.cornell.edu/uscode/text/38/3319","subs":["(h)(2)(A)","(h)(7)"],"by":{"0":"55, 57","1":"3, 30, 30, 31","2":"23"}},{"t":"usc","label":"38 U.S.C. § 3322","url":"https://www.law.cornell.edu/uscode/text/38/3322","subs":["(a)","(b)","(d)","(h)","(h)(1)"],"stext":{"head":"§3322. Bar to duplication of educational assistance benefits","paras":[[0,"(a) In General.—An individual entitled to educational assistance under this chapter who is also eligible for educational assistance under chapter 30, 31, 32, or 35 of this title, chapter 107, 1606, or 1607 or section 510 of title 10, or the provisions of the Hostage Relief Act of 1980 (Public Law 96–449; 5 U.S.C. 5561 note) may not receive assistance under two or more such programs concurrently, but shall elect (in such form and manner as the Secretary may prescribe) under which chapter or provisions to receive educational assistance."],[0,"(b) Inapplicability of Service Treated Under Educational Loan Repayment Programs.—A period of service counted for purposes of repayment of an education loan under chapter 109 of title 10 may not be counted as a period of service for entitlement to educational assistance under this chapter."],[0,"(c) Service in Selected Reserve.—An individual who serves in the Selected Reserve may receive credit for such service under only one of this chapter, chapter 30 of this title, and chapters 1606 and 1607 of title 10, and shall elect (in such form and manner as the Secretary may prescribe) under which chapter such service is to be credited."],[0,"(d) Additional Coordination Matters.—In the case of an individual entitled to educational assistance under chapter 30, 31, 32, or 35 of this title, chapter 107, 1606, or 1607 of title 10, or the provisions of the Hostage Relief Act of 1980, or making contributions toward entitlement to educational assistance under chapter 30 of this title, as of August 1, 2009, coordination of entitlement to educational assistance under this chapter, on the one hand, and such chapters or provisions, on the other, shall be governed by the provisions of section 5003(c) of the Post-9/11 Veterans Educational Assistance Act of 2008."],[0,"(e) Bar To Concurrent Receipt of Transferred Education Benefits and Marine Gunnery Sergeant John David Fry Scholarship Assistance.—An individual entitled to educational assistance under both section 3319 and paragraph (8), (9), or (10) of section 3311 of this title may not receive assistance under both provisions concurrently, but shall elect (in such form and manner as the Secretary may prescribe) under which provision to receive educational assistance."],[0,"(f) Bar To Receipt of Compensation and Pension and Marine Gunnery Sergeant John David Fry Scholarship Assistance.—The commencement of a program of education under paragraph (8), (9), or (10) of section 3311 of this title shall be a bar to the following:"],[1,"(1) Subsequent payments of dependency and indemnity compensation or pension based on the death of a parent to an eligible person over the age of 18 years by reason of pursuing a course in an educational institution."],[1,"(2) Increased rates, or additional amounts, of compensation, dependency and indemnity compensation, or pension because of such a person, whether eligibility is based upon the death of the parent."],[0,"(g) Bar To Concurrent Receipt of Transferred Education Benefits.—A spouse or child who is entitled to educational assistance under this chapter based on a transfer of entitlement from more than one individual under section 3319 may not receive assistance based on transfers from more than one such individual concurrently, but shall elect (in such form and manner as the Secretary may prescribe) under which source to utilize such assistance at any one time."],[0,"(h) Bar To Duplication of Eligibility Based on a Single Event or Period of Service.—"],[1,"(1) Active-duty service.—An individual with qualifying service in the Armed Forces that establishes eligibility on the part of such individual for educational assistance under this chapter, chapter 30 or 32 of this title, and chapter 1606 or 1607 of title 10, shall elect (in such form and manner as the Secretary may prescribe) under which authority such service is to be credited."],[1,"(2) Eligibility for educational assistance based on parent's service.—A child of a member of the Armed Forces who, on or after September 11, 2001, dies in the line of duty while serving on active duty, who is eligible for educational assistance under either chapter 35 or paragraph (8), (9), or (10) of section 3311 of this title based on the parent's death may not receive such assistance under both this chapter and chapter 35 of this title, but shall elect (in such form and manner as the Secretary may prescribe) under which chapter to receive such assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3322?type=usc&year=mostrecent&link-type=html"},"by":{"0":"11, 19, 20, 40, 50, 52, 53, 55, 60","1":"3, 30, 3, 30, 3, 30, 3, 30, 3, 30, 3, 30, 3, 30","2":"4, 13, 15, 16, 18"},"q":[{"src":"brief","b":0,"text":"elect . . . under which chapter or provisions to receive educational assistance.","cite":"38 U.S.C. § 3322(a)"},{"src":"brief","b":0,"text":"[b]ar to duplication of educational assistance benefits.","cite":"38 U.S.C. § 3322"},{"src":"brief","b":1,"text":"may not receive assistance under two or more such programs concurrently, but shall elect (in such form and manner as the [VA] may prescribe) under which chapter or provisions to receive educational assistance.","cite":"38 U.S.C. 3322(a)"},{"src":"brief","b":1,"text":"coordination of entitlement to [Post-9/11 benefits], on the one hand, and [Montgomery benefits], on the other, shall be governed by [38 U.S.C. 3327].","cite":"38 U.S.C. 3322(d)"},{"src":"brief","b":2,"text":"[a]n individual entitled to educational assistance under [two or more GI Bill programs] may not receive assistance under two or more such programs concurrently, but shall elect . . . under which chapter or provisions to receive educational assistance.","cite":"38 U.S.C. § 3322(a)"}]},{"t":"usc","label":"38 U.S.C. § 3327","url":"https://www.law.cornell.edu/uscode/text/38/3327","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(1)(B)","(a)(1)(E)","(a)(2)","(d)","(d)(1)","(d)(2)","(d)(2)(A)","(g)","(h)(1)","(i)"],"stext":{"head":"§3327. Election to receive educational assistance","paras":[[0,"(a) Individuals Eligible To Elect Participation in Post-9/11 Educational Assistance.—An individual may elect to receive educational assistance under this chapter if such individual—"],[1,"(1) as of August 1, 2009—"],[2,"(A) is entitled to basic educational assistance under chapter 30 of this title and has used, but retains unused, entitlement under that chapter;"],[2,"(B) is entitled to educational assistance under chapter 107, 1606, or 1607 of title 10 and has used, but retains unused, entitlement under the applicable chapter;"],[2,"(C) is entitled to basic educational assistance under chapter 30 of this title but has not used any entitlement under that chapter;"],[2,"(D) is entitled to educational assistance under chapter 107, 1606, or 1607 of title 10 but has not used any entitlement under such chapter;"],[2,"(E) is a member of the Armed Forces who is eligible for receipt of basic educational assistance under chapter 30 of this title and is making contributions toward such assistance under section 3011(b) or 3012(c) of this title; or"],[2,"(F) is a member of the Armed Forces who is not entitled to basic educational assistance under chapter 30 of this title by reason of an election under section 3011(c)(1) or 3012(d)(1) of this title; and"],[1,"(2) as of the date of the individual's election under this paragraph, meets the requirements for entitlement to educational assistance under this chapter."],[0,"(b) Cessation of Contributions Toward GI Bill.—Effective as of the first month beginning on or after the date of an election under subsection (a) of an individual described by paragraph (1)(E) of that subsection, the obligation of the individual to make contributions under section 3011(b) or 3012(c) of this title, as applicable, shall cease, and the requirements of such section shall be deemed to be no longer applicable to the individual."],[0,"(c) Revocation of Remaining Transferred Entitlement.—"],[1,"(1) Election to revoke.—If, on the date an individual described in paragraph (1)(A) or (1)(C) of subsection (a) makes an election under that subsection, a transfer of the entitlement of the individual to basic educational assistance under section 3020 of this title is in effect and a number of months of the entitlement so transferred remain unutilized, the individual may elect to revoke all or a portion of the entitlement so transferred that remains unutilized."],[1,"(2) Availability of revoked entitlement.—Any entitlement revoked by an individual under this subsection shall no longer be available to the dependent to whom transferred, but shall be available to the individual instead for educational assistance under chapter 33 of this title in accordance with the provisions of this section."],[1,"(3) Availability of unrevoked entitlement.—Any entitlement described in paragraph (1) that is not revoked by an individual in accordance with that paragraph shall remain available to the dependent or dependents concerned in accordance with the current transfer of such entitlement under section 3020 of this title."],[0,"(d) Post-9/11 Educational Assistance.—"],[1,"(1) In general.—Subject to paragraph (2) and except as provided in subsection (e), an individual making an election under subsection (a) shall be entitled to educational assistance under this chapter in accordance with the provisions of this chapter, instead of basic educational assistance under chapter 30 of this title, or educational assistance under chapter 107, 1606, or 1607 of title 10, as applicable."],[1,"(2) Limitation on entitlement for certain individuals.—In the case of an individual making an election under subsection (a) who is described by paragraph (1)(A) of that subsection, the number of months of entitlement of the individual to educational assistance under this chapter shall be the number of months equal to—"],[2,"(A) the number of months of unused entitlement of the individual under chapter 30 of this title, as of the date of the election, plus"],[2,"(B) the number of months, if any, of entitlement revoked by the individual under subsection (c)(1)."],[0,"(e) Continuing Entitlement to Educational Assistance Not Available Under Post-9/11 Educational Assistance Program.—"],[1,"(1) In general.—In the event educational assistance to which an individual making an election under subsection (a) would be entitled under chapter 30 of this title, or chapter 107, 1606, or 1607 of title 10, as applicable, is not authorized to be available to the individual under the provisions of this chapter, the individual shall remain entitled to such educational assistance in accordance with the provisions of the applicable chapter."],[1,"(2) Charge for use of entitlement.—The utilization by an individual of entitlement under paragraph (1) shall be chargeable against the entitlement of the individual to educational assistance under this chapter at the rate of 1 month of entitlement under this chapter for each month of entitlement utilized by the individual under paragraph (1) (as determined as if such entitlement were utilized under the provisions of chapter 30 of this title, or chapter 107, 1606, or 1607 of title 10, as applicable)."],[0,"(f) Additional Post-9/11 Assistance for Members Having Made Contributions Toward GI Bill.—"],[1,"(1) Additional assistance.—In the case of an individual making an election under subsection (a) who is described by subparagraph (A), (C), or (E) of paragraph (1) of that subsection, the amount of educational assistance payable to the individual under this chapter as a monthly stipend payable under paragraph (1)(B) of section 3313(c) of this title, or under paragraphs (2) through (7) 1 of that section (as applicable), shall be the amount otherwise payable as a monthly stipend under the applicable paragraph increased by the amount equal to—"],[2,"(A) the total amount of contributions toward basic educational assistance made by the individual under section 3011(b) or 3012(c) of this title, as of the date of the election, multiplied by"],[2,"(B) the fraction—"],[3,"(i) the numerator of which is—"],[4,"(I) the number of months of entitlement to basic educational assistance under chapter 30 of this title remaining to the individual at the time of the election; plus"],[4,"(II) the number of months, if any, of entitlement under chapter 30 of this title revoked by the individual under subsection (c)(1); and"],[3,"(ii) the denominator of which is 36 months."],[1,"(2) Months of remaining entitlement for certain individuals.—In the case of an individual covered by paragraph (1) who is described by subsection (a)(1)(E), the number of months of entitlement to basic educational assistance remaining to the individual for purposes of paragraph (1)(B)(i)(II) shall be 36 months."],[1,"(3) Timing of payment.—The amount payable with respect to an individual under paragraph (1) shall be paid to the individual together with the last payment of the monthly stipend payable to the individual under paragraph (1)(B) of section 3313(c) of this title, or under paragraphs (2) through (7) 1 of that section (as applicable), before the exhaustion of the individual's entitlement to educational assistance under this chapter."],[0,"(g) Continuing Entitlement to Additional Assistance for Critical Skills or Specialty and Additional Service.—An individual making an election under subsection (a)(1) who, at the time of the election, is entitled to increased educational assistance under section 3015(d) of this title, or section 16131(i) of title 10, or supplemental educational assistance under subchapter III of chapter 30 of this title, shall remain entitled to such increased educational assistance or supplemental educational assistance in the utilization of entitlement to educational assistance under this chapter, in an amount equal to the quarter, semester, or term, as applicable, equivalent of the monthly amount of such increased educational assistance or supplemental educational assistance payable with respect to the individual at the time of the election."],[0,"(h) Alternative Election by Secretary.—"],[1,"(1) In general.—In the case of an individual who, on or after January 1, 2017, submits to the Secretary an election under this section that the Secretary determines is clearly against the interests of the individual, or who fails to make an election under this section, the Secretary may make an alternative election on behalf of the individual that the Secretary determines is in the best interests of the individual."],[1,"(2) Notice.—If the Secretary makes an election on behalf of an individual under this subsection, the Secretary shall notify the individual by not later than seven days after making such election and shall provide the individual with a 30-day period, beginning on the date of the individual's receipt of such notice, during which the individual may modify or revoke the election made by the Secretary on the individual's behalf. The Secretary shall include, as part of such notice, a clear statement of why the alternative election made by the Secretary is in the best interests of the individual as compared to the election submitted by the individual. The Secretary shall provide the notice required under this paragraph by electronic means whenever possible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3327?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 20, 21, 22, 23, 29, 42, 44, 45, 46, 51, 56, 57","1":"2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2","2":"4, 12, 14, 16, 20, 21"},"q":[{"src":"brief","b":0,"text":"elect[ed] to receive educational assistance under [the Post-9/11 program].","cite":"38 U.S.C. § 3327(a)(1)(A)"},{"src":"brief","b":0,"text":"the number of months of entitlement of the individual to educational assistance under [the Post-9/11 program] shall be the number of months equal to . . . the number of months of unused entitlement of the individual under [the Montgomery program], as of the date of the election.","cite":"38 U.S.C. § 3327(d)(2)(A)"},{"src":"brief","b":1,"text":"as of the date of the election.","cite":"38 U.S.C. 3327(d)(2)(A)"},{"src":"brief","b":1,"text":"In the case of an individual making an election under subsection (a) who is described by paragraph (1)(A) of that subsection, the number of months of [Post-9/11 benefits] shall be * * * equal to * * * the number of months of unused [Montgomery benefits].","cite":"38 U.S.C. 3327(d)(2)(A)"},{"src":"brief","b":2,"text":"[a]n individual [described in the various subsections within Subsection 3327(a)] may elect to receive educational assistance under [the Post-9/11 GI Bill].","cite":"38 U.S.C. § 3327(a)"},{"src":"argument","who":"Mr. Tseytlin","text":"In Section 3327 of the same Act, Congress created a generous benefits coordination regime wherein veterans who had earned peacetime Montgomery veteran -- benefits with post-9/11 service could trade the unused portion of those Montgomery benefits for Post-9/11 benefits."}]},{"t":"usc","label":"38 U.S.C. § 3681","url":"https://www.law.cornell.edu/uscode/text/38/3681","by":{"0":"11"}},{"t":"usc","label":"38 U.S.C. § 3695","url":"https://www.law.cornell.edu/uscode/text/38/3695","subs":["(a)","(a)(3)","(a)(4)","(a)(5)","(a)(8)"],"stext":{"head":"§3695. Limitation on period of assistance under two or more programs","paras":[[0,"(a) The aggregate period for which any person may receive assistance under two or more of the provisions of law listed below may not exceed 48 months (or the part-time equivalent thereof):"],[1,"(1) Parts VII or VIII, Veterans Regulation numbered 1(a), as amended."],[1,"(2) Title II of the Veterans' Readjustment Assistance Act of 1952."],[1,"(3) The War Orphans' Educational Assistance Act of 1956."],[1,"(4) Chapters 30, 32, 33, 34, and 36."],[1,"(5) Chapters 107, 1606, 1607, and 1611 of title 10."],[1,"(6) Section 903 of the Department of Defense Authorization Act, 1981 (Public Law 96–342, 10 U.S.C. 2141 note)."],[1,"(7) The Hostage Relief Act of 1980 (Public Law 96–449, 5 U.S.C. 5561 note)."],[1,"(8) The Omnibus Diplomatic Security and Antiterrorism Act of 1986 (Public Law 99–399)."],[0,"(b) No person may receive assistance under chapter 31 of this title in combination with assistance under any of the provisions of law cited in subsection (a) of this section in excess of 48 months (or the part-time equivalent thereof) unless the Secretary determines that additional months of benefits under chapter 31 of this title are necessary to accomplish the purposes of a rehabilitation program (as defined in section 3101 of this title) in the individual case."],[0,"(c) The aggregate period for which any person may receive assistance under chapter 35 of this title, on the one hand, and any of the provisions of law referred to in subsection (a), on the other hand, may not exceed 81 months (or the part-time equivalent thereof)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3695?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 11, 40, 53, 60","1":"24, 33, 33, 33, 33, 33","2":"4, 21"},"q":[{"src":"brief","b":1,"text":"Limitation on period of assistance under two or more pro- grams,","cite":"38 U.S.C. 3695"},{"src":"brief","b":1,"text":"[t]he aggregate period for which any person may receive assistance under two or more of the provisions of law listed below may not exceed 48 months (or the part-time equivalent thereof ).","cite":"38 U.S.C. 3695(a)"}]},{"t":"usc","label":"38 U.S.C. § 4100","url":"https://www.law.cornell.edu/uscode/text/38/4100","by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 82-550","url":"https://www.govinfo.gov/link/statute/66/663","by":{"0":"6, 11, 12","2":"19, 23"}},{"t":"law","label":"Pub. L. No. 89-358","url":"https://www.govinfo.gov/link/statute/80/12","by":{"0":"7, 11, 12, 18"}},{"t":"law","label":"Pub. L. No. 90-631","url":"https://www.govinfo.gov/link/statute/82/1331","by":{"0":"11"}},{"t":"law","label":"Pub. L. No. 94-502","url":"https://www.govinfo.gov/link/statute/90/2383","by":{"0":"7"}},{"t":"reg","label":"38 C.F.R. § 21.4020","url":"https://www.ecfr.gov/current/title-38/section-21.4020","by":{"0":"27"}},{"t":"reg","label":"38 C.F.R. § 21.4022","url":"https://www.ecfr.gov/current/title-38/section-21.4022","by":{"0":"12, 24, 54","2":"23"}},{"t":"reg","label":"38 C.F.R. § 21.5022","url":"https://www.ecfr.gov/current/title-38/section-21.5022","by":{"0":"12"}},{"t":"reg","label":"38 C.F.R. § 21.7042","url":"https://www.ecfr.gov/current/title-38/section-21.7042","by":{"0":"12"}},{"t":"reg","label":"38 C.F.R. § 21.7143","url":"https://www.ecfr.gov/current/title-38/section-21.7143","by":{"0":"12, 24, 54","2":"23"},"q":[{"src":"brief","b":0,"text":"specify[ing] under which program her or she is claiming benefits","cite":"38 C.F.R. § 21.7143(b)"}]},{"t":"reg","label":"38 C.F.R. § 21.7540","url":"https://www.ecfr.gov/current/title-38/section-21.7540","by":{"0":"12"}},{"t":"reg","label":"38 C.F.R. § 21.7642","url":"https://www.ecfr.gov/current/title-38/section-21.7642","by":{"0":"12, 24"}},{"t":"reg","label":"38 C.F.R. § 21.9520","url":"https://www.ecfr.gov/current/title-38/section-21.9520","by":{"0":"27"}},{"t":"reg","label":"38 C.F.R. § 21.9635","url":"https://www.ecfr.gov/current/title-38/section-21.9635","by":{"0":"24, 54","2":"23"}},{"t":"reg","label":"38 C.F.R. § 21.9640","url":"https://www.ecfr.gov/current/title-38/section-21.9640","by":{"0":"15, 49"}},{"t":"reg","label":"38 C.F.R. § 21.9690","url":"https://www.ecfr.gov/current/title-38/section-21.9690","by":{"0":"24"}},{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"by":{"1":"31"}},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"ordinarily resist reading words or elements into a statute that do not appear on its face.","cite":"522 U.S. 23, 29"}]},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"by":{"1":"31"},"q":[{"src":"opinion","who":"Justice Thomas, dissenting","text":"interpretive doubt is to be resolved in the veteran's favor.","cite":"513 U. S. 115, 118"}]},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"When confronted with two Acts of Congress allegedly touching on the same topic, this Court is not at liberty to pick and choose among congressional enactments and must instead strive to give effect to both.","cite":"138 S. Ct. 1612, 1624"}]},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"cannot replace the actual text with speculation as to Congress’ intent.","cite":"582 U.S. 79, 89"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"presume differences in language like this convey differences in meaning.","cite":"582 U. S. 79, 86"}]},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"1":"20"}},{"t":"case","label":"Lamie v. United States Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"The starting point in discerning congressional intent is the existing statutory text, * * * and not the predecessor statutes.","cite":"540 U.S. 526, 534"},{"src":"brief","b":1,"text":"by comparing the present statute with its predecessor[s].","cite":"540 U.S. at 533"}]},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"hardships are to be remedied by payment of Government funds, it must be at the instance of Congress.","cite":"496 U.S. 414, 434"}]},{"t":"case","label":"Pavelic & LeFlore v. Marvel Entertainment Group","cite":"493 U.S. 120","y":1989,"id":"1989/88-791","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"task is to apply the text, not to improve upon it.","cite":"493 U.S. 120, 126"}]},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"1":"24"}},{"t":"case","label":"Railroad Trainmen v. Baltimore & Ohio R.R.","cite":"331 U.S. 519","y":1947,"id":"scdb/1946-111","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"can do no more than indicate the provisions in a most general manner.","cite":"331 U.S. 519, 528"}]},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"Atextual judicial supplementation is particularly inappropriate when, as here, Congress has shown that it knows how to adopt the omitted language or provision.","cite":"140 S. Ct. 355, 361"}]},{"t":"case","label":"United Benefit Life Insurance Co. v. United States Life Insurance Co.","cite":"36 F.3d 1063","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/36/1063/","by":{"1":"14"}},{"t":"const","label":"Article I, Section 8, Clause 12","text":"To raise and support Armies, but no Appropriation of Money to that Use shall be for a longer Term than two Years;","by":{"1":"28"}},{"t":"usc","label":"38 U.S.C. § 3020","url":"https://www.law.cornell.edu/uscode/text/38/3020","subs":["(h)(2)","(h)(6)"],"by":{"1":"3, 30, 30, 31"},"q":[{"src":"brief","b":1,"text":"in the same manner as the individual from whom the entitlement was transferred,","cite":"38 U.S.C. 3020(h)(2), 3319"}]},{"t":"usc","label":"38 U.S.C. § 3031","url":"https://www.law.cornell.edu/uscode/text/38/3031","by":{"1":"3"}},{"t":"usc","label":"38 U.S.C. § 3321","url":"https://www.law.cornell.edu/uscode/text/38/3321","by":{"1":"3"}},{"t":"usc","label":"38 U.S.C. § 1521","url":"https://www.law.cornell.edu/uscode/text/38/1521","by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"for an aggregate of ninety days or more in two or more separate periods of service.","cite":"38 U.S.C. 1521"}]},{"t":"reg","label":"Post-9/11 GI Bill, 73 Fed. Reg. 78,876","url":"https://www.govinfo.gov/link/fr/73/78876","by":{"1":"33","2":"24"}},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"by":{"2":"14"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"2":"8"},"q":[{"src":"brief","b":2,"text":"this Court is not free to ‘rewrite the statute’ to the Government’s liking.’","cite":"583 U.S. 109, 123"}]},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"by":{"2":"8"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"by":{"2":"22"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"by":{"2":"14"}},{"t":"case","label":"Sullivan v. Finkelstein","cite":"496 U.S. 617","y":1990,"id":"1989/89-504","sc":1,"by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"subsequent legislative history . . . should not be taken seriously.","cite":"496 U.S. 617, 631–32"}]},{"t":"usc","label":"10 U.S.C. § 16132","url":"https://www.law.cornell.edu/uscode/text/10/16132","by":{"2":"20"}},{"t":"law","label":"Pub. L. No. 110-252","url":"https://www.govinfo.gov/link/plaw/110/public/252","by":{"2":"19"}},{"t":"law","label":"Pub. L. No. 111-377","url":"https://www.govinfo.gov/link/plaw/111/public/377","by":{"2":"21"}}]};